package lk.repairdesk.api.dto; import jakarta.validation.constraints.*; import java.math.BigDecimal; import java.time.LocalDate; public final class WorkDtos {private WorkDtos(){} public record DiagnosisRequest(@NotBlank @Size(max=2000) String summary,boolean repairable,@DecimalMin("0") @DecimalMax("100") BigDecimal estimatedSuccessRate){} public record QuotationRequest(@PositiveOrZero BigDecimal labourCost,@PositiveOrZero BigDecimal partsCost,@PositiveOrZero BigDecimal tax,@FutureOrPresent LocalDate validUntil,@Size(max=1000) String notes){} public record RecommendationRequest(@Positive BigDecimal currentValue,@PositiveOrZero BigDecimal repairCost,@Min(0) int deviceAgeMonths,@Min(0) int previousRepairCount,@DecimalMin("0") @DecimalMax("100") BigDecimal successRate,boolean partsAvailable){} }